/**
 * Every Table subclass basename -> the mathml override family
 * its render goes through, measured off method ownership:
 * `matrix` (`table/matrix.rb:26`), `array` (`table/array.rb:19`),
 * `bmatrix` (`table/bmatrix.rb`), and `base` for the rest — the
 * intent-only wrappers (`Vmatrix`, `Pmatrix`, `Eqarray`, `Cases`)
 * render-verified byte-identical to the base table at
 * intent: false, the only intent this port reaches (intent is
 * deferred).
 */
export const MATHML_TABLE_NAME_FAMILIES: ReadonlyMap<string, string> = new Map([
  ["Align", "base"],
  ["Array", "array"],
  ["Bmatrix", "bmatrix"],
  ["Cases", "base"],
  ["Eqarray", "base"],
  ["Matrix", "matrix"],
  ["Multline", "base"],
  ["Pmatrix", "base"],
  ["Split", "base"],
  ["Vmatrix", "base"],
]);
